#!/bin/bash
# Builds build/windows/AiberTyper.exe (64-bit; Windows on ARM runs it emulated) from macOS, Linux or Windows (Git Bash).
# Needs Go only: the icon, manifest and version info are generated by cmd/rsrc, then go build cross-compiles.
# VERSION=1.2.3 sets the version Windows shows in the file properties (default 0.1, like the Mac build).
set -euo pipefail
cd "$(dirname "$0")"
go run ./cmd/rsrc ../../design/brand/icon-1024.png app/rsrc_windows_amd64.syso "${VERSION:-0.1}"
mkdir -p ../../build/windows
GOOS=windows GOARCH=amd64 CGO_ENABLED=0 go build -trimpath -ldflags "-H windowsgui -s -w" -o ../../build/windows/AiberTyper.exe ./app
echo "Built build/windows/AiberTyper.exe"
